INSERT INTO `v1_a4c2fd7dcba1d52c86587d8d1282efbfc897f39455d91e134294284613e725cb` VALUES (9, 40, 6, "サレンディア救護院", "植田佳奈", "B", 12, "泣き虫で臆病な守ってあげたい女の子", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 0, "観劇、おままごと", 108501, "ヒューマン", 150, "クルミ（クリスマス）", 9);
